<script setup lang="ts">
import {usePayrollPage} from '../payrollPage'
import type {PaymentMethod,PrDocument} from '../payrollTypes'
import type {ChangeProfileWrite} from '../payChanges'
import PayRuleFields from './PayRuleFields.vue'
import PayChangePrSourceFields from './PayChangePrSourceFields.vue'
import CdacProfileFields from './CdacProfileFields.vue'
const props=defineProps<{profile:ChangeProfileWrite;birthDate?:string;prDocuments:PrDocument[];prConfirmed:boolean;busy:boolean}>()
const emit=defineEmits<{'update:prConfirmed':[confirmed:boolean]}>()
const {english}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
function changePayment(event:Event){const method=(event.target as HTMLSelectElement).value;props.profile.payment=['cash','bank','paynow','other'].includes(method)?{method:method as PaymentMethod,bank:method==='cash'?'':props.profile.payment?.bank||''}:null}
</script>
<template><PayRuleFields :rule="profile.rule" :disabled="busy"/><section class="wf-section"><h3>{{x('扣缴与付款设置','Contributions and payment')}}</h3><div class="wf-grid"><label>{{x('公民身份','Citizenship')}}<select v-model="profile.cpf.citizenship"><option value="citizen">{{x('公民','Citizen')}}</option><option value="spr">{{x('永久居民','Permanent resident')}}</option><option value="foreign">{{x('外籍','Foreign')}}</option></select></label><label>{{x('出生日期','Birth date')}}<input v-model="profile.cpf.birthDate" type="date" :readonly="!!birthDate" :required="profile.cpf.citizenship!=='foreign'"></label></div><div v-if="profile.cpf.citizenship==='spr'" class="wf-grid"><PayChangePrSourceFields :cpf="profile.cpf" :documents="prDocuments" :confirmed="prConfirmed" @update:confirmed="emit('update:prConfirmed',$event)"/><label>{{x('PR缴费模式','PR contribution mode')}}<select v-model="profile.cpf.prMode"><option>GG</option><option>FG</option><option>FF</option></select></label><label v-if="profile.cpf.prMode!=='GG'">{{x('缴费选择依据','Election reference')}}<textarea v-model="profile.cpf.electionReference" required maxlength="500"/></label></div><button v-if="!profile.cdac" type="button" @click="profile.cdac={status:'not_applicable',reference:''}">{{x('设置CDAC','Configure CDAC')}}</button><CdacProfileFields v-else :setting="profile.cdac" :items="profile.rule.items" :citizenship="profile.cpf.citizenship" configured/><label>{{x('付款方式','Payment method')}}<select :value="profile.payment?.method||''" @change="changePayment"><option value="">{{x('未设置','Unspecified')}}</option><option value="cash">{{x('现金','Cash')}}</option><option value="bank">{{x('银行','Bank')}}</option><option value="paynow">PayNow</option><option value="other">{{x('其他','Other')}}</option></select></label><label v-if="profile.payment&&profile.payment.method!=='cash'">{{x('银行／付款资料','Bank / payment details')}}<input v-model="profile.payment.bank" maxlength="100" :required="profile.payment.method==='bank'"></label></section></template>
